CREATE TABLE return_requests(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,order_id BIGINT NOT NULL REFERENCES orders(id),reason TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN ('requested','authorized','received','inspected','approved','completed','rejected')),created_by BIGINT NOT NULL REFERENCES users(id),approved_by BIGINT REFERENCES users(id),version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ);
CREATE TABLE return_items(return_id BIGINT REFERENCES return_requests(id),order_item_id BIGINT REFERENCES order_items(id),quantity INTEGER NOT NULL CHECK(quantity>0),condition TEXT NOT NULL CHECK(condition IN ('sealed','opened','damaged')),PRIMARY KEY(return_id,order_item_id));
INSERT INTO permissions(code) VALUES('returns.manage'),('refunds.approve') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r CROSS JOIN permissions p WHERE (r.name='admin' AND p.code IN ('returns.manage','refunds.approve')) OR (r.name IN ('warehouse','sales') AND p.code='returns.manage') OR (r.name='finance' AND p.code='refunds.approve') ON CONFLICT DO NOTHING;
